import type {CoreAPI, Loader, LoaderOptions} from '@loaders.gl/loader-utils';
import type {Vector3} from '@math.gl/core';
import type {TilesetTraverser, TilesetTraverserProps} from './tileset-traverser';
import type {Tile3D} from './tile-3d';
import type {Tileset3D} from './tileset-3d';
import type {FrameState} from '../helpers/frame-state';
import type {TILESET_TYPE} from '../../constants';
import type {TilesetSpatialReference} from '../../spatial/spatial-types';
import type {Tile3DContent} from './tile-3d-contracts';

/**
 * Parsed top-level tileset payload consumed by {@link Tileset3D} or a {@link Tileset3DSource}.
 */
export type TilesetJSON = any;

/**
 * Resource-loading strategy used by source implementations to fetch and parse root metadata
 * and tile resources.
 */
export type TilesetSourceResolver = {
  /**
   * Loads and parses the root metadata resource for a source.
   */
  loadRoot<DataT>(url: string, loader: Loader<DataT>, loadOptions: LoaderOptions): Promise<DataT>;

  /**
   * Loads and parses an arbitrary source-relative resource.
   */
  loadResource<DataT>(
    url: string,
    loader: Loader<DataT>,
    loadOptions: LoaderOptions
  ): Promise<DataT>;
};

/**
 * URL-based source input used when a source is responsible for fetching root metadata.
 */
export type TilesetSourceRequest = {
  /** Absolute root metadata URL. */
  url: string;
  /** Loader used to fetch and parse the root metadata. */
  loader: Loader;
  /** Optional base path override for relative resources. */
  basePath?: string;
  /** Optional resource-loading strategy used for archive-backed datasets. */
  resolver?: TilesetSourceResolver;
  /** Optional core API implementation used for nested source loading. */
  coreApi?: CoreAPI;
};

/**
 * Constructor input accepted by explicit source implementations.
 *
 * Request descriptors are the public path. Preloaded metadata remains useful for tests and
 * internal call sites that already own parsed root metadata.
 */
export type TilesetSourceInput = TilesetJSON | TilesetSourceRequest;

/**
 * Result of a source-managed tile content request.
 */
export type TileContentLoadResult = {
  /** Whether the tile content request produced usable content. */
  loaded: boolean;
  /** All payloads loaded for a tile, in source order. */
  contents?: any[];
  /** Optional normalized renderer-neutral descriptors for each content entry. */
  contentEntries?: Tile3DContent[];
  /** Nested tileset metadata to install below the loaded tile, if any. */
  nestedTileset?: TilesetJSON;
  /** Nested tilesets found among multiple content payloads. */
  nestedTilesets?: TilesetJSON[];
};

/** Result of a source-managed lazy child-header request. */
export type TileChildrenLoadResult = {
  /** Whether a subtree resource was loaded and installed. */
  loaded: boolean;
  /** Number of available tiles described by the subtree, including its existing root placeholder. */
  tileCount: number;
  /** Number of lazy child-subtree references installed at the new boundary. */
  childSubtreeCount: number;
};

/**
 * Flags describing compression and texture formats observed while streaming tile content.
 */
export type TilesetContentFormats = {
  draco: boolean;
  meshopt: boolean;
  dds: boolean;
  ktx2: boolean;
};

/**
 * Optional view-state metadata exposed by a {@link Tileset3DSource} after initialization.
 */
export type TilesetSourceViewState = {
  cartographicCenter?: Vector3 | null;
  cartesianCenter?: Vector3 | null;
  zoom?: number;
  boundingVolume?: any;
  description?: string;
  properties?: any;
  extras?: any;
  credits?: any;
  asset?: Record<string, any>;
};

/**
 * Normalized source metadata consumed by {@link Tileset3D}.
 */
export type TilesetSourceMetadata = {
  /** Format discriminator. */
  type: TILESET_TYPE;
  /** Primary format loader used for metadata and default content requests. */
  loader: Loader;
  /** Absolute root metadata URL. */
  url: string;
  /** Base path used for relative resource resolution. */
  basePath: string;
  /** Parsed and normalized source payload. */
  tileset: TilesetJSON;
  /** Root lod metric type used as fallback by runtime tiles. */
  lodMetricType: string;
  /** Root lod metric value used as fallback by runtime tiles. */
  lodMetricValue: number;
  /** Root refinement mode used as fallback by runtime tiles. */
  refine: string;
  /** Format-discovered coordinate reference system metadata. */
  spatialReference?: TilesetSpatialReference;
};

/**
 * Format-specific adapter used by {@link Tileset3D} for initialization, loading, and metadata access.
 */
export interface Tileset3DSource {
  /** Tileset format discriminator. */
  readonly type: TILESET_TYPE;
  /** Primary format loader used for metadata and default content requests. */
  readonly loader: Loader;
  /** Absolute URL of the root tileset resource. */
  readonly url: string;
  /** Base directory used for relative resource resolution. */
  readonly basePath: string;
  /** Source-specific root tileset payload, when available. */
  readonly tileset?: TilesetJSON | null;
  /** Loader options forwarded to metadata and content requests. */
  readonly loadOptions: LoaderOptions;
  /** Core API used for source-managed loads, when injected by the caller. */
  coreApi?: CoreAPI;
  /** Accumulated content-format flags for the tileset. */
  readonly contentFormats: TilesetContentFormats;
  /** Format-specific asset metadata, if any. */
  asset?: Record<string, any>;
  /** Per-feature property schema, if any. */
  properties?: any;
  /** Application-specific root metadata, if any. */
  extras?: any;
  /** Attribution and credit metadata, if any. */
  credits?: any;

  /** Normalized source metadata after initialization. */
  metadata?: TilesetSourceMetadata;

  /**
   * Initializes source state before traversal begins.
   */
  initialize(): Promise<void>;

  /**
   * Prepares option-dependent asynchronous source state before runtime headers are constructed.
   *
   * I3S uses this hook to sample elevation surfaces for its root bound after `Tileset3D` has
   * applied spatial options. Sources without asynchronous header preparation omit the hook.
   */
  prepareTileset?(tileset: Tileset3D): Promise<void>;

  /** Releases source-local caches and prevents late asynchronous work from mutating runtime tiles. */
  destroy?(): void;

  /**
   * Returns normalized source metadata after initialization completes.
   */
  getMetadata(): TilesetSourceMetadata;

  /**
   * Returns the root tileset payload after source initialization completes.
   */
  getRootTileset(): Promise<TilesetJSON>;

  /**
   * Creates the runtime tile tree for a tileset payload or nested subtree.
   */
  initializeTileHeaders(
    tileset: Tileset3D,
    tilesetJson: TilesetJSON,
    parentTile?: Tile3D | null
  ): Tile3D;

  /**
   * Creates the traverser implementation appropriate for this source.
   */
  createTraverser(options: TilesetTraverserProps): TilesetTraverser;

  /**
   * Loads renderable content for a tile.
   */
  loadTileContent(tile: Tile3D): Promise<TileContentLoadResult>;

  /**
   * Loads and installs a complete lazy child-header group for a runtime tile.
   *
   * Sources that implement this hook retain ownership of resource parsing, caching, query
   * inheritance, and archive resolution. Traversal calls it only after visibility and LOD checks.
   */
  loadTileChildren?(tile: Tile3D, frameState: FrameState): Promise<TileChildrenLoadResult>;

  /**
   * Loads all source-managed child headers without requiring camera or visibility state.
   *
   * This hook is used by complete dataset operations such as conversion. Implementations retain
   * ownership of implicit subtrees, node pages, archive resolution, and query inheritance.
   */
  loadTileChildrenForTraversal?(
    tile: Tile3D,
    signal?: AbortSignal
  ): Promise<TileChildrenLoadResult>;

  /**
   * Resolves a tile-relative path to the final request URL.
   */
  getTileUrl(tilePath: string): string;

  /**
   * Returns tileset-level view metadata derived from the loaded source.
   */
  getViewState(rootTile: Tile3D | null): TilesetSourceViewState;

  /**
   * Checks whether the source declares a specific extension.
   */
  hasExtension?(extensionName: string): boolean;

  /**
   * Loads child tile metadata on demand for formats that do not expose the full tree up front.
   */
  loadChildTileHeader?(
    parentTile: Tile3D,
    childId: string,
    frameState: FrameState | null
  ): Promise<any>;

  /**
   * Updates source-managed bookkeeping after a tile finishes loading.
   */
  onTileLoaded?(tileset: Tileset3D, tile: Tile3D, loadResult: TileContentLoadResult): void;

  /**
   * Returns the total known tile count for stats, if available.
   */
  getTilesTotalCount?(): number | null;
}

/**
 * Type guard for distinguishing a source-backed constructor input from other runtime values.
 * @param value Value to test.
 * @returns `true` when the value implements the {@link Tileset3DSource} contract.
 */
export function isTileset3DSource(value: unknown): value is Tileset3DSource {
  return Boolean(
    value &&
      typeof value === 'object' &&
      'initialize' in value &&
      'getRootTileset' in value &&
      'initializeTileHeaders' in value &&
      'loadTileContent' in value
  );
}
